begin;
create table if not exists public.edge_user_rate_limits(user_id uuid not null,scope text not null,window_started_at timestamptz not null default now(),hit_count integer not null default 0,updated_at timestamptz not null default now(),primary key(user_id,scope));
alter table public.edge_user_rate_limits enable row level security; revoke all on public.edge_user_rate_limits from public,anon,authenticated;
create or replace function public.edge_user_rate_limit(p_scope text,p_limit integer,p_window_seconds integer) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$
declare uid uuid:=(select auth.uid());r public.edge_user_rate_limits%rowtype;now_at timestamptz:=clock_timestamp();lim int:=greatest(1,least(coalesce(p_limit,60),500));win int:=greatest(10,least(coalesce(p_window_seconds,3600),86400));safe_scope text:=left(regexp_replace(coalesce(p_scope,''),'[^a-zA-Z0-9:_-]','','g'),80);
begin if uid is null or coalesce(auth.role(),'')<>'authenticated' then raise exception 'Authentication required.' using errcode='insufficient_privilege';end if;if safe_scope='' then raise exception 'Invalid scope.' using errcode='invalid_parameter_value';end if;insert into public.edge_user_rate_limits(user_id,scope,window_started_at,hit_count,updated_at) values(uid,safe_scope,now_at,1,now_at) on conflict(user_id,scope) do update set window_started_at=case when public.edge_user_rate_limits.window_started_at+make_interval(secs=>win)<=now_at then now_at else public.edge_user_rate_limits.window_started_at end,hit_count=case when public.edge_user_rate_limits.window_started_at+make_interval(secs=>win)<=now_at then 1 else public.edge_user_rate_limits.hit_count+1 end,updated_at=now_at returning * into r;return jsonb_build_object('allowed',r.hit_count<=lim,'remaining',greatest(0,lim-r.hit_count),'retry_after',case when r.hit_count>lim then greatest(1,ceil(extract(epoch from(r.window_started_at+make_interval(secs=>win)-now_at))))::int else 0 end);end $$;
revoke execute on function public.edge_user_rate_limit(text,integer,integer) from public,anon;grant execute on function public.edge_user_rate_limit(text,integer,integer) to authenticated;commit;
